        "question": "W jakim paśmie pracuje Bluebird S10 RFID?",
        "answer": "W ofercie jest wersja na europejskie pasmo UHF 865–868 MHz. Wersji na pasmo 902–928 MHz nie oferujemy, bo nie jest przeznaczona do pracy w Unii Europejskiej."
